$find = $pdo->prepare('SELECT s.id,e.title FROM learn_english_rpg_scenes s JOIN learn_english_rpg_episodes e ON e.id=s.episode_id WHERE e.code=? AND s.sort_order=?');
$update = $pdo->prepare('UPDATE learn_english_rpg_scenes SET prompt=?, choices_json=? WHERE id=?');
foreach ($contexts as $code => $data) {
    foreach ([7, 14] as $index => $sort) {
        $find->execute([$code, $sort]); $scene = $find->fetch(PDO::FETCH_ASSOC);
        if (!$scene) continue;
        $choices = $index === 0
            ? [['text'=>$data[1][0],'choice_code'=>'compassion','reputation_delta'=>2,'feedback'=>'Your kindness helps the people nearby.'],['text'=>$data[1][1],'choice_code'=>'courage','reputation_delta'=>1,'feedback'=>'Your courage makes the next step safer.'],['text'=>$data[1][2],'choice_code'=>'wisdom','reputation_delta'=>1,'feedback'=>'Your careful thinking reveals a useful clue.']]
            : [['text'=>$data[2][1][0],'choice_code'=>'mercy','reputation_delta'=>2,'feedback'=>'Working together opens a peaceful path.'],['text'=>$data[2][1][1],'choice_code'=>'valor','reputation_delta'=>1,'feedback'=>'Your brave choice protects the people with you.'],['text'=>$data[2][1][2],'choice_code'=>'insight','reputation_delta'=>1,'feedback'=>'The clue reveals a thoughtful way forward.']];
        $prompt = $index === 0 ? $data[0] : $data[2][0];
        $update->execute([$prompt, json_encode($choices, JSON_UNESCAPED_UNICODE), $scene['id']]);
    }
}

$dialogues = [
    ['mountain_camp',7,'A storm rolls over the mountain trail. Which meaning of “storm” will guide your next step?'],
    ['pirate_islands',7,'Dark clouds surround the emerald islands. Learn “storm” before the crew chooses a safe route.'],
    ['space_station',13,'The word “crew” flashes on the station console. Choose its meaning to break the dark spell.'],
    ['pirate_islands',13,'The captain calls out “crew” as the ship enters the mist. What does the word mean?'],
    ['ocean_treasure',8,'The reef guardian raises a shield and asks about “protect”. Answer to enter the coral court.'],
    ['dragon_academy',8,'A dragon guardian tests the word “protect” before opening the academy gate.'],
];
$updateDialogue = $pdo->prepare('UPDATE learn_english_rpg_scenes s JOIN learn_english_rpg_episodes e ON e.id=s.episode_id SET s.dialogue=? WHERE e.code=? AND s.sort_order=?');
foreach ($dialogues as $item) $updateDialogue->execute([$item[2], $item[0], $item[1]]);
echo "Updated ".count($contexts)." story chapters.\n";
